function countOddSlices(nums: number[], k: number): number {
  let total = 0;
  for (let i = 0; i < nums.length; i++) {
    let odds = 0;
    for (let j = i; j < nums.length; j++) {
      odds += nums[j] % 2;
      if (odds === k) total++;
      else if (odds > k) break;
    }
  }
  return total;
}

