function countOddSlices(nums: number[], k: number): number {
  const seen = new Map<number, number>([[0, 1]]);
  let odds = 0, total = 0;
  for (const x of nums) {
    odds += x % 2;
    total += seen.get(odds - k) ?? 0;
    seen.set(odds, (seen.get(odds) ?? 0) + 1);
  }
  return total;
}

