function countOddSlices(nums: number[], k: number): number {
  const atMost = (m: number): number => {
    let left = 0, odds = 0, total = 0;
    for (let right = 0; right < nums.length; right++) {
      odds += nums[right] % 2;
      while (odds > m) odds -= nums[left++] % 2;
      total += right - left + 1;
    }
    return total;
  };
  return atMost(k) - atMost(k - 1);
}

